function PatrolTeamPanel:FreshBaseUI(data)
    if data and data.useItemId then
        self.isUseItem = true
        self.useItemId = data.useItemId
        self.usedCB = data.usedCB
    end
    local isBackFromCultivate = KCookie.Get("CultivateBackToPatrolTeamPanel") == 1
    if isBackFromCultivate then
        MazeMgr:FreshMazeData(function()
            KCookie.Set("CultivateBackToPatrolTeamPanel", 0)
            self:FillSelf()
        end)
    else
        self:FillSelf()
    end
end

