function PatrolTeamPanel:OnGetItemByIndex(go, index)
    if index < 0 or index > #self.roleDatas - 1 then
        return nil
    end
    --local item = loopView:NewListViewItem("hero")
    local item = go
    --print("===go.name--->>"..go.name)
    local cardPar = item.transform:Find("head")
    if not cardPar then
        cardPar = item.transform:Find("AnimRoot/head")
    end
    local role = self.roleDatas[index + 1]

    local cardData = mazeTeamComp:GetFakeRoleData(role.id)

    if not self._smallCardLoader then
        self._smallCardLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
    end
    if self._smallCardLoader.IsSuccess then
        local go = cardPar.transform:Find("cell")
        if not go then
            go = CfUtils.InstantiateGo(self._smallCardLoader.ResultObject, cardPar)
            go.name = "cell"
        end
        if go then
            CfUtils.RefeshCommonSmallHeroGo(go, cardData, Vector3(0.75, 0.75, 1), function()
                if self.isUseItem then
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.useItemId, Constants.IDArea.Maze)
                    if goodsVo.effectType == Constants.GoodsEffectType.MazeCure then
                        --回复血量
                        if checkNumber(role.hpPercent) >= 1 then
                            GameUtils.Toast(localize("满血不要使用"), 1)
                        elseif checkNumber(role.hpPercent) <= 0 then
                            GameUtils.Toast(localize("角色已死亡，不能回复血量"), 1)
                        else
                            -----使用物品
                            GameUtils.SecondConfirm(localize("是否对该角色使用该道具？"), function()
                                MazeMgr:GetInstance():MazeUseGoods(self.useItemId, role.isAssistant, role.id)
                                --UIModule.CloseDialog(self.controller)
                                --KTool.SetActive(self.controller, false)
                                if self.usedCB then
                                    self.usedCB()
                                end
                                GameUtils.Toast(localize("已对该角色使用道具"))
                            end, nil, goodsVo.description)
                        end
                    else
                        ---使用物品
                        GameUtils.Toast(localize("已对该角色使用道具"))
                        MazeMgr:GetInstance():MazeUseGoods(self.useItemId, role.isAssistant, role.id)
                        UIModule.BackDialog()

                        --KTool.SetActive(self.controller, false)
                    end
                else
                    --if checkNumber(role.isAssistant) == 1 then
                    --    CardUtils.ShowCardPreview({previewType = Constants.UICultivateCardPreviewType.Virtual, cards = {cardData}}, {
                    --        {id = Constants.UITypeIds.PatrolMainDialog},
                    --        {id = Constants.UITypeIds.PatrolBtnLeftNodeDialog},
                    --        {id = Constants.UITypeIds.PatrolChooseRolePopup}
                    --    })
                    --else
                    --    KCookie.Set("CultivateBackToPatrolTeamPanel", 1)
                    --    CardUtils.ShowCultivateMain({selectCardDojo = cardData}, {
                    --        {id = Constants.UITypeIds.PatrolMainDialog},
                    --        {id = Constants.UITypeIds.PatrolBtnLeftNodeDialog},
                    --        {id = Constants.UITypeIds.PatrolChooseRolePopup}
                    --    })
                    --end
                    --CfUtils.RefreshTopCommonEntrance()
                    --MazeMgr:GetInstance():CloseMazeMainGameObject()
                end
            end)
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end
    local hpGo = item.transform:Find("CommonHpEnergyNode")
    if not hpGo then
        hpGo = item.transform:Find("AnimRoot/CommonHpEnergyNode")
    end
    self._uiCommonHpAndEnergyNodeScr = CfUtils.GetLuaScr(hpGo, UICommonHpAndEnergyNode)
    if self._uiCommonHpAndEnergyNodeScr then
        --print("energy-->>"..table.dump(role))
        self._uiCommonHpAndEnergyNodeScr:Refresh(role)
    end
    KTool.SetActive(item.transform:Find("AnimRoot/StateGroup/support"), checkNumber(role.isAssistant) == 1)
    return item
end

function PatrolTeamPanel:SortRoles(roleDatas)
    if not roleDatas then
        return roleDatas
    end

    table.sort(roleDatas, function(a, b)
        local cardVo1 = CardConfMgr:GetInstance():GetCardByRefId(a.cardId)
        local cardVo2 = CardConfMgr:GetInstance():GetCardByRefId(b.cardId)

        if not cardVo1 then
            return true
        elseif not cardVo2 then
            return false
        end

        if self.isUseItem then
            if a.hpPercent < b.hpPercent then
                return true
            end
        else
            if checkNumber(cardVo1.rare) > checkNumber(cardVo2.rare) then
                return true
            elseif checkNumber(cardVo1.rare) == checkNumber(cardVo2.rare) then
                if checkNumber(a.cardLevel) > checkNumber(b.cardLevel) then
                    return true
                end
            end
        end

        return false
    end)
end
