        self._smallCardLoader:Release()
        self._smallCardLoader = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolTeamPanel
